"""Check native Terrain orchestration using fixtures generated by the JS reference."""
from pathlib import Path
import argparse
import json
import subprocess


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    for name in ('probe','input','expected','shader','output'):parser.add_argument('--'+name,type=Path,required=True)
    args=parser.parse_args();args.output.mkdir(parents=True,exist_ok=True)
    actual=args.output/'terrain-result.json'
    subprocess.run([str(args.probe.resolve()),str(args.input.resolve()),str(args.shader.resolve()),str(actual.resolve())],check=True)
    found=json.loads(actual.read_text());expected=json.loads(args.expected.read_text());assert len(found)==len(expected)
    maximum=0
    for n,(a,b) in enumerate(zip(found,expected)):
        for key in ('mode','next_row','history'):assert a[key]==b[key],(n,key)
        assert len(a['uniforms'])==len(b['uniforms'])
        for index,(value,wanted) in enumerate(zip(a['uniforms'],b['uniforms'])):
            difference=abs(value-wanted);maximum=max(maximum,difference)
            assert difference<=.00001,(n,index,value,wanted)
    result={'result':'pass','frames':len(found),'half_float_history':'exact','camera_and_palette_uniform_maximum_error':maximum,
            'reference':'Terrain64/assets/terrain/adapter.mjs, pre-generated fixtures'}
    (args.output/'comparison.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result))


if __name__=='__main__':main()
